  // Epilogue: store results for both register-blocked output pixels
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    const int ow = ow_a + i;
    if ((oh < Hout) && (ow < Wout)) {
      #pragma unroll
      for (int j = 0; j < CPerThread; ++j) {
        const int c = c_base + cw0 + j;
        if (c < Cout) {
          mY(c, oh, ow) = static_cast<T>(acc[i][j]);
        }
      }
    }
